        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.root", "Looking for supplies or help with your implants? I can handle both. I also know where a few relic caches are.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.about", "I buy and sell useful hardware, and I can help when your implants put too much strain on you. Ask what you need; I\u0027ll tell you the price.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.work", "I sell supplies and give cache leads. My strain buffer offers temporary relief; a neural reset clears psychosis and active doses. Neither repairs cyberware.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.advice", "A cache is easier to open when nobody is shooting at you. Clear the area, check the breach sequences, then start picking tokens.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.trust", "Pay your way and treat me fairly. As we build trust, you\u0027ll get better prices and access to more services.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.terms", "Prices are listed before you pay. A neural reset needs more trust and is available once per world day. It also clears suppression and RAM Jolt.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.shop", "Let me see what you\u0027re selling.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.services", "What services do you offer?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.contracts", "Show me the available contracts.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.cache", "Do you know of any relic caches nearby?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.talk", "Can I ask you a few questions?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.work", "What can you help me with?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.advice", "Any advice before I head out?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.trust", "How can I earn your trust?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.goodbye", "That\u0027s everything. See you around.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.terms", "What are your prices and conditions?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.back", "What else can you help me with?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.thanks", "Thanks. I\u0027ll keep that in mind.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.understood", "Understood.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.agreed", "That sounds fair.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.root", "Need treatment or medical supplies? Take a look at the services and stock. If you\u0027re worried about your implants, we can talk first.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.about", "I keep people running when their cyberware starts wearing them down. I also sell medical supplies and a few basic implants.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.work", "Clinic care restores health and reduces cyberstrain. Detox removes harmful effects and clears neural pressure. Use a Repair Station for worn implants.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.advice", "More chrome means more strain. Watch your integrity and cyberstrain readings, and repair damaged implants before relying on them in a fight.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.trust", "Coming back, paying for treatment and speaking respectfully build trust. Detox treatment unlocks once I know you better.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.terms", "Detox requires more trust and is available once per world day. It clears active neural doses too. Treatment prices are shown on each card.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.player.shop", "Let me see what you\u0027re selling.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.player.services", "What services do you offer?");
