        add("screen.cyberneticenhancements.npc.dialogue.techie.line.root", "Need parts, a temporary tune-up or a contract? Pick one. We can talk shop afterward.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.about", "I work with cyberware and workshop supplies. I sell practical kit and offer contracts that can help pay for your next build.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.work", "Open Contracts to see my jobs. Repairs, upgrades and recycling happen at stations; my services offer mining speed or protection for hazardous work.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.advice", "Learn the schematic before buying fabrication materials. Keep useful salvage, and repair a good implant before spending resources on its next upgrade.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.trust", "Finish my contracts, buy supplies and keep your word. Better trust means better prices and access to hazard preparation.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.terms", "Mining calibration gives Haste II. Hazard preparation gives fire resistance and damage resistance. Both last five minutes; neither upgrades an implant.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.player.shop", "Let me see what you\u0027re selling.");
