        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.root", "Need equipment, a contract or a relic-cache location? I can help. I also offer recon support and a stealth protocol.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.about", "I work with data and neural hardware. I sell memory and RAM equipment, offer contracts and keep a few cache locations on record.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.work", "Read the contract objective before accepting. Delivery means leaving the provided package in the marked Iron Quest Crate; extraction means taking the shard from one and bringing it back.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.advice", "Before a breach, look for token sequences that overlap. Your first pick starts the timer. Plan before you commit.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.trust", "Complete my contracts and be reliable. Trust unlocks better prices and the stealth protocol. Just browsing costs nothing.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.terms", "Recon support gives night vision and speed for eight minutes. Stealth gives invisibility and speed for three minutes. Armor stays visible.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.player.shop", "Let me see what you\u0027re selling.");
