        add("screen.cyberneticenhancements.npc.dialogue.merc.line.root", "Looking for work or supplies? I\u0027ve got contracts, combat kit and temporary field support. Tell me what you need.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.about", "I take dangerous work and sell kit for people doing the same. Read the job, bring what you need and come back alive.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.work", "Open Contracts for the job list. Check the objective: not every contract is a kill order. Return when the work is finished to collect payment.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.advice", "Check your health, implant condition and supplies before heading out. Use cover. A better plan is cheaper than replacing your gear.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.trust", "Finish your contracts and buy supplies. Trust unlocks combat preparation and better prices. Abandoning jobs makes me trust you less.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.terms", "Field recovery gives regeneration and absorption. Combat preparation gives strength and resistance for three minutes. Preparation needs more trust.");
