        add("message.cyberneticenhancements.encounter.ripperdoc", "A street ripperdoc is heading your way from about %s blocks off. They carry real chrome and will wait %s minutes if they cannot reach you, or if you ignore them.");
        add("message.cyberneticenhancements.encounter.shakedown", "A gang closes in on you. \"Toll's %s eurodollars, choom. You've got %s seconds.\"");
