        add("wiki.cyberneticenhancements.quest_guide.limits", "One active contract per contact, with no total limit. Boards refresh each Minecraft day. Use the compass to follow the active objective.");
        add("wiki.cyberneticenhancements.quest_guide.tiers", "Trust level 0 offers tier 1. Level 1 unlocks tier 2; level 3 unlocks tier 3. Each available tier is equally likely when an offer is generated.");
        add("wiki.cyberneticenhancements.quest_guide.urgent", "Urgent contracts pay 25% more money (rounded up) and +1 extra trust. Tier summaries show normal payouts.");
        add("wiki.cyberneticenhancements.quest_guide.guaranteed", "Money, trust, XP and listed supplies are guaranteed on successful turn-in. Amounts and discovery chances use this server's economy settings.");
        add("wiki.cyberneticenhancements.quest_guide.discovery_rule", "One separate bonus roll awards a missing schematic, or a fallback part if all eligible designs are learned. The pool updates as designs are learned. Tier 3 Cyberpsycho jobs roll for a restricted core first; a core replaces the schematic/part bonus.");
        add("wiki.cyberneticenhancements.quest_guide.delivery", "In-person turn-ins give items immediately. Remote turn-ins pay money, trust and XP immediately; items arrive at your Dropoff Point within one Minecraft day.");
        add("wiki.cyberneticenhancements.quest_guide.failure", "Failed or abandoned contracts pay no completion rewards. Abandonment costs at least 2 trust, or the contract's trust reward +2 if higher. A failed breach has no second attempt.");
        add("wiki.cyberneticenhancements.quest_guide.turn_in_person", "Hold the required item and right-click the issuing NPC to hand it over without opening dialogue. Keep the full requested quantity in your inventory. Dialogue turn-in is also available.");
        add("wiki.cyberneticenhancements.quest_guide.turn_in_report", "Nothing needs to be carried back. Walk up to the issuing NPC and tell them in person, through dialogue, to complete the quest.");
