        add("wiki.cyberneticenhancements.status.mark.periodic", "Periodic behavior: target outline highlighting for follow-up attacks.");
        add("wiki.cyberneticenhancements.status.shock.visual", "Visual identity: cyan-white sparks, electric dust and violent body jitter.");
        add("wiki.cyberneticenhancements.status.shock.intent", "This status is meant to read as electrical seizure, not a generic potion effect.");
        add("wiki.cyberneticenhancements.status.overheat.visual", "Visual identity: flame, ember dust, smoke plumes and heat rings.");
        add("wiki.cyberneticenhancements.status.overheat.intent", "This status is meant to read as internal thermal overload.");
        add("wiki.cyberneticenhancements.status.corrosion.visual", "Visual identity: toxic yellow-green dust, runoff and corrosive drip lines.");
        add("wiki.cyberneticenhancements.status.corrosion.intent", "This status is meant to read as chemical breakdown.");
        add("wiki.cyberneticenhancements.status.trauma.visual", "Visual identity: red impact dust, damage bursts and heavy shock pulses.");
        add("wiki.cyberneticenhancements.status.trauma.intent", "This status is meant to read as blunt internal damage.");
        add("wiki.cyberneticenhancements.status.bleed.visual", "Visual identity: crimson dust and directional trailing spray while moving.");
        add("wiki.cyberneticenhancements.status.bleed.intent", "This status is meant to read as active bleeding under exertion.");
        add("wiki.cyberneticenhancements.status.mark.visual", "Visual identity: cyan-green targeting rings plus the shared outline renderer.");
