    private void addCallDialogue() {
        callVariants("greeting.med_tech", "MedTec here. Are you hurt, or do you need supplies?", "Medical channel open. How can I help?", "You reached MedTec. Tell me what you need.");
        callVariants("services.med_tech", "I provide medical supplies, clinical stabilization, and coverage for one emergency rescue dispatch. Come see me to arrange them.", "Need treatment or emergency coverage? Visit me in person and we can get you prepared.", "I can help with medical supplies and stabilization. Arrange your rescue coverage before you head into danger.");
        callVariants("advice.med_tech", "Keep medical supplies close and arrange coverage before trouble starts. Responders still need to reach you.", "If you go down with coverage, choose Call MedTec. Keep in mind that respawning abandons the rescue.", "Coverage buys you a chance, not invincibility. Avoid dangerous terrain where responders cannot reach you.");
        callVariants("incoming.money.med_tech", "We are restocking medical supplies. Could you contribute €$%s? This is a favor, not a coverage payment.", "Could you spare €$%s for field medical supplies? No pressure if you cannot.", "A busy shift has left us short on supplies. Would you help with €$%s? Your coverage is separate.");
        callVariants("greeting.world_med_tech", "MedTec field team. Did something go wrong with the patient?", "This is MedTec. Is the patient still alive?", "MedTec field channel. Talk to me.");
        callVariants("services.world_med_tech", "We only have the one job: the patient. Nothing else is for sale out here.", "No shop out here. Save the patient and we will settle up.", "Field team only. Bring the beacon back and you are paid.");
        callVariants("advice.world_med_tech", "Revive them with the injector first, then use the beacon right beside them. Lose either one and the patient is lost.", "Do not drop the injector or the beacon. We cannot replace them out here.", "The beacon logs wherever you stand, so stand next to the patient. I will check, and I do not take kindly to lies.");
        callVariants("quest.help.locate", "Find the patient sitting against a wall in the marked area. Use the injector on them, log your position beside them with the beacon, then bring the beacon to me.", "Search the marked area. Revive the patient with the injector, use the beacon right next to them, and return the beacon to me in person.", "Patient first, beacon right beside them, then back to me. Log a false position and you will answer for it. Lose an item and the contract fails.");
        callVariants("greeting.maxtec", "MaxTec patrol. Go ahead.", "This is MaxTec. What do you need?", "Patrol channel open. Keep it brief.");
        callVariants("services.maxtec", "I handle threats inside this city. Medical services and supplies come from other contacts.", "City protection is my assignment. I do not take private contracts.", "I can answer questions while the district is quiet. Hostile contacts take priority.");
        callVariants("advice.maxtec", "Give patrols room and stay clear of creepers.", "If you see a threat, keep your distance. We will handle what we can reach.", "Stay alert, protect the locals and keep your hands off the officers.");
        callVariants("incoming.money.maxtec", "Could use \u20ac$%s toward replacement equipment. Can you help?", "Restocking after a rough patrol. Could you spare \u20ac$%s?", "Would you contribute \u20ac$%s toward some replacement kit?");
        addIncomingCallDialogue();
        String prefix = "screen.cyberneticenhancements.call.";
        add(prefix + "choice.contracts", "Any contracts available?");
        add(prefix + "choice.active_contract", "About my current contract...");
        add(prefix + "choice.questions", "Can I ask you something?");
        add(prefix + "choice.small_talk", "How are things on your end?");
        add(prefix + "choice.services", "What can you help me with?");
        add(prefix + "choice.offer", "Tell me about %s.");
        add(prefix + "choice.more_contracts", "What other contracts do you have?");
        add(prefix + "choice.other_contracts", "Let me hear the other contracts.");
        add(prefix + "choice.accept_contract", "I'll take that contract.");
        add(prefix + "choice.quest_status", "How is my contract progressing?");
        add(prefix + "choice.quest_help", "What exactly do I need to do?");
        add(prefix + "choice.quest_location", "Where do I need to go?");
        add(prefix + "choice.report_contract", "The job is done. Send the payment.");
        add(prefix + "quest.briefing", "%s. %s Payment: %s. Interested?");
        add(prefix + "quest.accepted", "It's yours: %s. %s. Ask if you need the details again.");
        add(prefix + "quest.accepted_chat", "Contract accepted: %s. Contact: %s.");
        add(prefix + "quest.paid_chat", "Contract completed: %s. Reward: %s. Any item rewards will be delivered to your Dropoff Point.");
        add(prefix + "quest.paid_direct_chat", "Contract completed: %s. Reward: %s.");
        add(prefix + "quest.offer_gone", "That offer is no longer available. Let me check what I have now.");
        add(prefix + "quest.max_active", "This contact already has an active contract. Finish or abandon it before taking another from them.");
        add(prefix + "quest.no_active", "You aren't working a contract for me right now. Want to hear what's available?");
        add(prefix + "quest.status", "%s. %s. %s");
        add(prefix + "quest.in_progress", "It's still open. Ask me if you need the instructions or the destination again.");
        add(prefix + "quest.ready_remote", "The objective is complete. Turn it in here or through the archive. I'll credit your account now and send any item rewards to your Dropoff Point. Meet me in person if you want those items immediately.");
        add(prefix + "quest.ready_in_person", "Bring the required items to me in person. I need to receive them directly before I can pay you. Your HUD compass marks my location.");
        add(prefix + "quest.ready_report", "Come and tell me in person where you found them. I need to hear it from you before I can pay you. Your HUD compass marks my location.");
        add(prefix + "quest.report_unavailable", "I can't close this contract yet. Make sure the objective is complete and you still have any requested items.");
        add(prefix + "quest.location", "The site is at %s, %s, %s in %s. %s");
        add(prefix + "quest.location_navigation", "Follow the gold quest marker on your HUD compass. Its height indicator helps with underground and underwater sites.");
        add(prefix + "quest.location_investigation", "The HUD marker shows the survey area until you have three bearings, then it points to the source cache. Crouch with empty hands and stay still for three seconds to scan; move sideways between readings. Breach the cache once located.");
        add(prefix + "quest.no_site", "There is no fixed site for this job. Gather %s %s and bring them to me.");
        callVariants("back", "Anything else you need?", "All right. What else?", "I'm still here. What do you need?");
        callVariants("greeting.fixer", "Yeah, you've got me. What do you need?", "I've got a minute. Talk to me.", "Good timing. What's the plan?");
        callVariants("greeting.ripperdoc", "Clinic here. Everything all right?", "I'm between patients. How can I help?", "Go ahead. What do you need?");
        callVariants("greeting.techie", "Hey. Just putting the tools down. What's up?", "You caught me in the workshop. Go ahead.", "Yeah, I'm listening. Need work or directions?");
        callVariants("greeting.netrunner", "Your connection's clear. What's up?", "I'm here. Need a job, or a hand with one?", "Give me a second... All right, talk to me.");
        callVariants("greeting.merc", "Yeah? Make it quick, I'm keeping watch.", "I'm clear for a call. What do you need?", "You've got me. What's happening?");
        callVariants("greeting.night_sleepy", "You woke me up. This had better be worth it.", "Do you know what time it is? All right, I'm listening.", "I was asleep. Give me a second. What do you need?");
        callVariants("greeting.night_awake", "Still up too? All right, what's the job?", "Quiet night so far. What do you need?", "I wasn't sleeping. Go ahead.");
        callVariants("greeting.rain", "Hang on, getting out of this rain. Go ahead.", "It's pouring out here. Hope you've got something good.", "If you hear the rain, that's my end. What do you need?");
        callVariants("greeting.storm", "If the thunder cuts me off, call back. What's up?", "Great timing. I'm trying to find cover from this storm.", "Storm's right overhead. Let's make this quick.");
        callVariants("greeting.trusted", "Hey, good to hear from you. What do you need?", "For you? I've got time. Go ahead.", "There you are. How can I help?");
        callVariants("greeting.annoyed", "I'm answering, but don't push it. What do you want?", "Keep it short. We're not exactly on good terms.", "All right, one minute. Make it count.");
        callVariants("meeting.normal", "All right, I'll come to you. Talk to me when I get there.", "Stay there. I'll meet you in person.", "Sure. Ending the call and coming over now.");
        callVariants("meeting.rain", "Fine, but I'm going to get soaked coming to you. Find us some cover.", "In this rain? You owe me a dry place to stand. Coming over.", "I'll meet you, but get under a roof. I'm not discussing this in the rain.");
        callVariants("meeting.storm", "With that storm outside? All right, but find cover before I get there.", "You're picking quite a time for a meeting. Stay somewhere sheltered.", "I'll come, but let's keep out of the lightning. See you in a moment.");
        callVariants("meeting.night", "Dragging me out this late? Fine. Stay put.", "All right, a late-night meeting it is. I'm coming over.", "I'll come to you. Try to make this worth losing sleep over.");
        callVariants("cannot_meet", "I can't get to you right now. We need to be in the same dimension, and I need to be free.", "Not right now. We can keep talking, or try again when I'm free and we're in the same dimension.", "I can't make that meeting from here. Try again when we're in the same dimension and I'm available.");
        callVariants("location", "I'm at %s. Follow the blue outline; I've marked myself for you.", "Sending my position: %s. Look for the blue outline.", "You can find me at %s. I've turned on a blue locator outline.");
        callVariants("questions", "Sure. What do you want to know?", "Go ahead, I'm listening.", "Ask away. I'll tell you what I can.");
        callVariants("contracts", "I've got a few jobs. Pick one and I'll give you the details.", "There is work available. Which contract do you want to hear about?", "Let me check the board. These are the contracts I can offer you.");
        callVariants("no_contracts", "Nothing on my board right now. Check back tomorrow.", "No jobs available at the moment. Try me another day.", "I'm out of offers for now. I'll have another look tomorrow.");
        callVariants("quest.paid", "Confirmed. Sending your payment: %s.", "Good work. Your payment is on the way: %s.", "That's the job closed. You've earned %s.");
        callVariants("small_talk.normal", "Keeping busy. There's always another job waiting.", "Quiet for now. I'll take it while it lasts.", "Nothing I can't handle. How's your end of things?");
        callVariants("small_talk.night", "Trying to get through the night without another problem landing on my doorstep.", "It's late. I was hoping things would stay quiet for once.", "Ask me after I've had some sleep. For now, I'm managing.");
        callVariants("small_talk.rain", "Wet. Mostly wet. Looking forward to getting indoors.", "This rain's making everything take twice as long.", "I'd be doing better somewhere dry. Otherwise, can't complain.");
        callVariants("small_talk.annoyed", "I'd rather keep this to business right now.", "Let's not pretend everything's fine. What do you need?", "I'm not in the mood for small talk. We can still discuss work.");
        callVariants("services.fixer", "Supplies, strain buffers, neural resets and relic-cache leads. Come see me for stock and services.", "I can sell supplies, help with strain and point you toward a relic cache. Those arrangements need an in-person visit.", "Need supplies, a strain buffer or a cache lead? Find me in person and we'll sort it out.");
        callVariants("services.ripperdoc", "Clinic care, detox, medical supplies and basic implants. Come to me for treatment. Implant repairs need a Repair Station.", "I handle treatment, detox and medical stock. I can't examine or treat you over a call.", "I can help with injuries and strain, and sell medical supplies. For damaged cyberware, use a Repair Station.");
        callVariants("services.techie", "Workshop parts, mining calibration, hazard preparation and contracts. You can take a job on this call; parts and services need a visit.", "I can offer contracts remotely. Come to the workshop for components, mining support and hazard preparation.", "Jobs over the phone, parts and calibration in person. Ask about contracts if you want work.");
        callVariants("services.netrunner", "Equipment, recon support, stealth preparation, contracts and cache leads. We can arrange contracts on this call.", "I can brief you on jobs remotely. Equipment, recon services and cache leads need an in-person visit.", "Need a contract or help understanding one? We can do that here. Come see me for gear and services.");
        callVariants("services.merc", "Combat supplies, recovery, preparation and contracts. We can discuss jobs here; supplies and services need a visit.", "I can offer work and talk you through it remotely. Come see me for combat kit and preparation.", "Jobs on the phone, gear in person. I also offer recovery and combat preparation when you visit.");
        callVariants("advice.fixer", "Keep an eye on your strain. A buffer buys time; it doesn't make heavy chrome harmless.", "If you're hunting a relic cache, ask me in person. I can mark a known cache on your HUD compass.", "Don't spend your last eurodollar before a long trip. Leave enough for supplies or treatment.");
        callVariants("advice.ripperdoc", "If your cyberstrain keeps rising, stop and deal with it before taking on more trouble.", "Check implant integrity before a fight. Treatment and cyberware repair are different jobs.", "A damaged implant belongs at a Repair Station. Don't expect a medical consumable to fix the hardware.");
        callVariants("advice.techie", "Read your schematics before trying to fabricate the hardware. Knowing the recipe matters.", "Check your upgrade materials before committing. Some steps need more than basic parts.", "Recycling, repairing and upgrading use separate stations. Pick the one that actually does the job.");
        callVariants("advice.netrunner", "At a relic cache, plan your route through the matrix before spending the buffer.", "Don't assume you'll clear every cache reward. Pick the sequences worth chasing.", "If you're stuck on a contract, ask me for its objective or destination. Guessing wastes time.");
        callVariants("advice.merc", "Check your implant integrity and supplies before you take a fight.", "On a marked hunt, head to the contract site. The HUD compass marks it for you.", "If a job goes bad, take a moment to recover. Starting the next fight hurt rarely improves things.");
        callVariants("quest.help.delivery", "Take the package to the marked Iron Quest Crate and put it inside. Wait for confirmation; don't bring it back to me.", "Follow the delivery marker on your HUD compass, open the Iron Quest Crate and deposit the package. It may be underwater or underground.", "The package belongs in the marked Iron Quest Crate. Once the delivery registers, report back over this call for payment.");
        callVariants("quest.help.extraction", "Follow the extraction marker and collect the shard from the Iron Quest Crate. Bring it back to me in person for payment.", "Retrieve the exfil shard from the marked Iron Quest Crate, then hand it to me in person. A call or the archive cannot transfer the shard.", "Reach the marked Iron Quest Crate and take the shard. You must return it to me in person to finish the job and collect your rewards.");
        callVariants("quest.help.investigation", "Go to the survey area on your HUD compass. Crouch with both hands empty and stay still for three seconds. Take three bearings, moving 32 to 48 blocks sideways each time, then breach the source cache.", "Don't follow the same line for every reading. Spread your three scans around the survey area so their bearings intersect. The HUD will mark the source after triangulation; breach its cache to finish.", "You need three separated readings with different angles. Crouch, empty both hands and hold still to scan within 160 blocks of the survey marker. Once the source is located, recover its data by breaching the cache.");
        callVariants("quest.help.breach", "Follow the breach marker to the cache. You get one attempt, committed with your first selection. Running out of time, filling the buffer without completing every sequence, or closing mid-breach fails the job and costs trust.", "Find the marked cache and plan before your first selection. After that, you must finish the puzzle in one attempt. Failure costs trust; success lets you call me for payment.", "Use your HUD compass to find this contract's cache. It disappears after success. There is no retry after your first selection: failing or leaving the breach fails the contract and costs trust.");
        callVariants("quest.help.elimination", "Go to the marked hunt site and eliminate %s %s there. Kills elsewhere won't satisfy this contract.", "The contract needs %s %s taken down at the designated site. Use the hunt marker on your HUD compass and watch your progress.", "Follow the hunt marker on your HUD compass and defeat %s %s at the marked site. Once it's confirmed, report through this call.");
        callVariants("quest.help.recovery", "Gather %s %s and bring them to me in person. I need the actual materials before I can pay you.", "I need %s %s. Get them however you prefer, then meet me in person to hand them over.", "Bring me %s %s in person. There isn't a marked collection site; you're sourcing the materials yourself.");
        callVariants("quest.help.cyberpsycho", "The compass marks an approximate sighting. Search within 48 blocks, neutralize the cyberpsycho, then pick up their named dossier shard. Hand it to me in person for payment.", "Prepare for a heavily augmented opponent. Their red name means they are aggressive. Dodge launcher shots and blade lunges. Kill the target and bring their information shard to me in person.", "Find the cyberpsycho in the marked area. Killing them is only part of the job: collect the dossier from their body, then return it to me in person. These contracts have our highest payouts, and damaged cyberware sometimes survives the fight.");
    }

    private void addIncomingCallDialogue() {
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.6", "Contacts can call you. Answer with Alt+1 or decline with Alt+2; unanswered calls stop after 30 seconds. Connected NPCs hang up after 10 seconds without a conversation reply, with no trust or quest penalty. An issuer may check on a contract after two hours of online play time. Trusted contacts may occasionally ask for a small contribution, which you must explicitly approve; declining a money request costs nothing. Automatic calls have a 30-minute overall cooldown and a two-hour repeat cooldown per contract, money request or urgent issuer; these survive reconnects and respawns. Hidden contacts do not make routine calls; missing quest evidence can still trigger an angry call.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.7", "Contract issuers can occasionally call with a specific urgent job when you have no active contract from them. Answer to review the objective and boosted payout. Accepting through that offer adds 25% money and one extra trust to its completion rewards. Explicitly refusing the job costs one trust and withdraws that offer; missing or declining the ringing call costs nothing. Urgent contracts are labeled in the quest log and keep their bonus through saving and reconnects. Urgency does not add a completion deadline.");
        String prefix = "screen.cyberneticenhancements.call.";
        add(prefix + "incoming.title", "Incoming: %s");
        add(prefix + "incoming.ringing", "Incoming call...");
        add(prefix + "incoming.notice", "Incoming call from %s. Answer or decline using the call HUD.");
        add(prefix + "incoming.missed", "Missed call. The contact stopped ringing.");
        add(prefix + "incoming.quest_changed", "I was calling about that contract, but I see the situation has changed. Anything else you need?");
        add(prefix + "incoming.money_insufficient", "Looks like you don't have enough in your account. Don't worry about it.");
        add(prefix + "incoming.money_sent_chat", "Sent €$%s to %s.");
        add(prefix + "choice.answer", "Answer call");
        add(prefix + "choice.decline", "Decline call");
        add(prefix + "choice.send_money", "Send €$%s.");
        add(prefix + "choice.decline_money", "Sorry, I can't spare the money.");
        add(prefix + "choice.change_subject", "Can we talk about something else?");
        add(prefix + "choice.working_on_it", "I'm still working on it.");
        add(prefix + "choice.accept_urgent", "I'll take this job. (+25% pay, +1 trust)");
        add(prefix + "choice.decline_urgent", "I can't take it. (-1 trust)");
        add(prefix + "incoming.urgent_accepted", "%s is yours. %s Completion payout: %s. The urgency bonus is included.");
        add(prefix + "incoming.urgent_deadline", " You have %s minutes of online play to finish the objective.");
        add(prefix + "incoming.urgent_declined_chat", "Declined %s's urgent contract. Trust -1.");
        callVariants("incoming.urgent.techie", "Need this handled soon: %s. %s Payout: %s, including the urgency bonus. Can you take it?", "I've got an urgent job for you: %s. %s I'll pay %s on completion. You in?", "Calling about %s. I need help with this one. %s Completion pays %s, bonus included.");
        callVariants("incoming.urgent.netrunner", "An urgent contract came in: %s. %s Completion pays %s, with extra for taking it now. Can I count on you?", "Need someone for %s. %s I'll pay %s when it's done. That's the boosted rate.", "I've got priority work: %s. %s The payout is %s, urgency bonus included. Interested?");
        callVariants("incoming.urgent.merc", "Need a hand with %s. %s Completion pays %s, including extra for the urgency. Can you do it?", "Got an urgent job: %s. %s I'll pay %s on completion. You available?", "Calling you for %s. %s The pay is %s, bonus included. Can I put you on it?");
        callVariants("incoming.urgent_declined", "All right. I'll find someone else. I was counting on you for this one.", "Understood. I needed help on this, so that's disappointing. I'll make other arrangements.", "Fine. I'll ask someone else. I hoped I could rely on you here.");
        callVariants("incoming.checkin", "Hey, got a minute? Thought I'd check in. How can I help?", "It's me. Wanted to catch you while we both have a moment.", "Hey. Just checking that you're still out there. Need anything?");
        callVariants("incoming.overdue", "I'm calling about %s. You took that job hours ago. What's holding you up?", "Any news on %s? It's been a while since you accepted. Do you need the instructions again?", "We need to talk about %s. That contract's been open for hours. Are you still working on it?");
        callVariants("incoming.acknowledged", "All right. Keep me posted. Ask if you need the details again.", "Good. Let me know when you've got progress to report.", "Understood. I'm here if you need the destination or the instructions.");
        callVariants("incoming.money.fixer", "Quick favor. I'm covering a few expenses today. Can you spare €$%s? It's help, not a loan.", "Bit short on funds for an arrangement. Could you send €$%s? No pressure if you can't.", "Could use €$%s toward some expenses. You don't owe me anything; I'm asking as a contact.");
        callVariants("incoming.money.ripperdoc", "The clinic's running low on supplies. Could you contribute €$%s to the next order?", "I'm stocking up for patients. Could you spare €$%s toward the medical supplies?", "Small favor: €$%s would help cover clinic supplies. It's entirely up to you.");
        callVariants("incoming.money.techie", "A parts order came up short. Could you spare €$%s to help cover it?", "Need a little help keeping the workshop stocked. Could you contribute €$%s?", "I'm replacing some worn tools. Would you be willing to chip in €$%s?");
        callVariants("incoming.money.netrunner", "Cooked a piece of equipment. Could use €$%s toward a replacement. Can you help?", "I'm short on replacement hardware. Could you spare €$%s? No worries if not.", "Got an unexpected equipment bill. Would you chip in €$%s to help cover it?");
        callVariants("incoming.money.merc", "Restocking after a rough job. Could you spare €$%s for supplies?", "Could use €$%s toward some replacement kit. Can you help a contact out?", "Need to patch up my gear. Would you be willing to contribute €$%s?");
        callVariants("incoming.money_declined", "No problem. Had to ask. We can still talk business.", "Understood. Keep what you need. Anything else?", "Fair enough. Don't put yourself short on my account.");
        callVariants("incoming.money_thanks", "Received. Thanks, that helps. I appreciate it.", "Got it. You're doing me a favor here. Thank you.", "That came through. Thanks for helping out.");
        String command = "command.cyberneticenhancements.calls.";
        add(command + "not_npc", "Choose a Cybernetic Enhancements NPC.");
        add(command + "unavailable", "Call could not start. Check for an occupied line, an open container, an unavailable NPC, a missing overdue contract, or no eligible urgent offer from that contact.");
        add(command + "forced", "%s is calling %s (%s).");
        add(command + "started", "Started an eligible incoming call for %s.");
        add(command + "no_call", "No incoming call started for %s. Eligibility, cooldowns and normal urgent-offer / money-request randomness still apply.");
        add(command + "reset", "Reset incoming-call cooldowns for %s.");
        add(command + "status", "%s: %s minutes played; incoming-call cooldown: %s minutes; call active: %s.");
        add(command + "no_quest", "That player has no active contract from this NPC.");
        add(command + "aged", "Set the age of %s's active contract to %s minutes of play time.");
    }

